/* L7 ★ */
G(7,()=>CH('Как доказать, что наибольшее возможное значение в задаче равно M?','Оценка (больше M нельзя) + пример (M достигается)',['Достаточно привести пример, где получается M','Достаточно доказать, что больше M нельзя','Перебрать несколько вариантов и выбрать лучший'],
 {short:'Два ключа: оценка и пример.',
 explain:'Нужны <b>обе</b> части: 1) <b>оценка</b> — доказательство, что больше M получить нельзя; 2) <b>пример</b> — конкретная ситуация, где M получается. Без примера, может быть, и M недостижимо; без оценки, может быть, можно больше.',
 explain2:'Короли на доске 8×8: оценка — 16 квадратиков 2×2, в каждом не больше одного короля; пример — 16 королей «через клетку». Ответ 16 доказан.'}),'r');
G(7,()=>{const m=pick([3,4,5,7]);const sq=[...new Set(range(0,m-1).map(r=>r*r%m))];const never=range(0,m-1).filter(a=>!sq.includes(mod(-a,m)));const some=range(0,m-1).filter(a=>sq.includes(mod(-a,m)));
 const ra=pick(never);const aR=ra+m*R(0,3);const ws=sample(some,Math.min(3,some.length)).map(a=>a+m*R(0,3));while(ws.length<3){const a=pick(some)+m*R(4,8);if(!ws.includes(a))ws.push(a);}
 for(const a of [aR,...ws]){let can=false;for(let n=0;n<m*3;n++)if((n*n+a)%m===0)can=true;ok(can===(a!==aR),'n2+a');}
 return CH(`При каком из чисел a выражение n² + a <b>ни при каком</b> целом n не делится на ${m}?`,`a = ${aR}`,ws.map(a=>`a = ${a}`),{
 hint:`Перебери остатки n² при делении на ${m}.`,
 short:`n² ≡ ${sq.sort((x,y)=>x-y).join(', ')} (mod ${m}); n² + ${aR} ≡ ${sq.map(s=>(s+aR)%m).join(', ')} — нет нуля.`,
 explain:`Шаг 1. Остатки квадратов при делении на ${m}: <b>${sq.join(', ')}</b> (перебор n ≡ ${range(0,m-1).join(', ')}).<br>Шаг 2. n² + a делится на ${m}, если остаток n² равен остатку (−a). Для a = ${aR}: нужен остаток ${mod(-aR,m)} — среди квадратов его нет. Значит, <b>никогда</b>.<br>Шаг 3. Остальные: ${ws.map(a=>{const n=range(0,m-1).find(x=>(x*x+a)%m===0);return `a = ${a}: n = ${n} → ${n*n+a} делится на ${m}`;}).join('; ')}.`,
 explain2:`Это перебор случаев + контрпримеры: для «плохих» a достаточно одного n, где n² + a делится на ${m}, а для a = ${aR} перебор всех остатков показывает, что такого n нет.`});},'s');
G(7,()=>{const a=pick([2,3,4,7,8,9,13,17,22,33]);const n=R(20,2030);const cyc=[];let x=a%10;while(!cyc.includes(x)){cyc.push(x);x=x*a%10;}const st=cyc.indexOf(x);
 let r=1;for(let i=0;i<n;i++)r=r*a%10;
 const L=cyc.length-st;const pos=n<=st?n:st+((n-1-st)%L)+1;ok(cyc[pos-1]===r,'cycle');
 return {type:'num',q:`Какой цифрой оканчивается число ${a}<sup>${n}</sup>?`,ans:r,
 short:`Цикл ${cyc.join(', ')}; ${n} → ${r}.`,
 explain:`Шаг 1. Последняя цифра степени зависит только от последней цифры основания (${a%10}). Выписываем последние цифры ${a}¹, ${a}², …: <b>${cyc.join(', ')}</b>, дальше повторяется — цикл длины ${L}.<br>Шаг 2. ${n} = ${L} · ${Math.floor((n-st-1)/L)} + ${(n-1-st)%L+1}${st?` (с учётом начала цикла)`:''} → ${(n-1-st)%L+1}-е место в цикле.<br>Шаг 3. Ответ: <b>${r}</b>.`,
 explain2:`Это перебор случаев: остаток ${n} при делении на ${L} — ${n%L} — определяет последнюю цифру. Проверь на маленькой степени: ${a}<sup>${L+1}</sup> оканчивается на ${cyc[st]} — как ${a}<sup>${st+1}</sup>.`};},'s');
G(7,()=>{const steps=['База: в табуне из 1 лошади все лошади одного цвета.','Предположение: в любом табуне из n лошадей все лошади одного цвета.','Возьмём табун из n + 1 лошади. Уберём последнюю — остальные n одного цвета. Уберём первую — остальные n тоже одного цвета.','Эти две группы по n лошадей пересекаются, поэтому все n + 1 лошадей одного цвета.'];
 return {type:'choice',q:`Знаменитое «доказательство», что все лошади одного цвета:${PROOF(steps)}Где ошибка?`,opts:['В шаге 4: при n = 1 группы «без первой» и «без последней» не пересекаются','В шаге 1: табун из одной лошади может быть разноцветным','В шаге 2: нельзя ничего предполагать','В шаге 3: нельзя убирать лошадей из табуна'],ans:0,
 short:'Переход от 1 к 2 ломается: группы по одной лошади не пересекаются.',
 explain:'Шаги 1–3 честные. <b>Шаг 4</b> работает только при n ≥ 2. При n = 1 табун из 2 лошадей: «без последней» — только первая лошадь, «без первой» — только вторая. Общих лошадей нет, и сравнить цвета не через кого. Цепочка ломается в самом первом звене 1 → 2, а значит, и все дальнейшие переходы ничего не доказывают.',
 explain2:'Такое рассуждение называется «индукцией»: база + переход от n к n + 1. Переход должен работать для <b>каждого</b> n, начиная с базы. Здесь он не работает ровно при n = 1 — и этого достаточно, чтобы всё рухнуло.'};},'s');

/* ---------- widget: Euler's polynomial ---------- */
function onTheory(root){const w=root.querySelector('#w-euler');if(!w)return;
 w.innerHTML=`<b>Проверь гипотезу: n² + n + 41 — всегда простое?</b>
 <label>n = <input type="range" id="en" min="0" max="45" value="1"><output id="eno"></output></label>
 <div id="eout" style="font-size:17px;line-height:1.6;margin:6px 0"></div>
 <div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn ghost" id="eall">Проверить n = 0…39 сразу</button><button class="btn ghost" id="efind">Найти контрпример</button></div>
 <div id="elog" style="margin-top:8px;font-size:15px;line-height:1.5"></div>`;
 const $=id=>w.querySelector('#'+id);
 const u=()=>{const n=+$('en').value;$('eno').textContent=n;const v=n*n+n+41;const p=isP(v);
  $('eout').innerHTML=`${n}² + ${n} + 41 = <b>${v}</b> — ${p?'<span style="color:var(--ok);font-weight:700">простое ✅</span>':`<span style="color:var(--bad);font-weight:700">составное: ${factor(v).join(' · ')} ❌ Это контрпример!</span>`}`;};
 $('en').oninput=u;$('en').onchange=u;
 $('eall').onclick=()=>{const bad=range(0,39).filter(n=>!isP(n*n+n+41));$('elog').innerHTML=`Проверено 40 значений (n = 0…39): ${bad.length?'есть составные':'<b>все простые!</b>'} Кажется, гипотеза верна… Но 40 примеров — это не доказательство. Попробуй n = 40.`;};
 $('efind').onclick=()=>{let n=0;while(isP(n*n+n+41))n++;$('en').value=n;u();$('elog').innerHTML=`Первый контрпример: n = ${n}. ${n}² + ${n} + 41 = ${n*n+n+41} = ${factor(n*n+n+41).join(' · ')}. Одного контрпримера хватило, чтобы опровергнуть утверждение «для всех n».`;};
 u();}

